import{_ as d,a8 as a,o as i,c as u,au as p,a as g,a3 as o,K as r,L as l}from"./chunks/framework.B0pOEyz7.js";import"./chunks/theme.Cfhi2zoU.js";const x=JSON.parse('{"title":"Cursor 删掉了自动记忆，这可能是三家 Agent 里最诚实的选择","description":"","frontmatter":{"title":"Cursor 删掉了自动记忆，这可能是三家 Agent 里最诚实的选择","abstract":"Cursor 自 2.1.x 起移除 chat Memories，理由是\\"和规则差别不大\\"。于是记忆被拆成两件事：稳定约定归 rules，历史信息归本地检索。代价是失去\\"越用越懂你\\"，收益是不会被过期记忆带偏。","created":"2026-11-09T00:00:00.000Z","updated":"2026-11-10T00:00:00.000Z","type":"调研","tags":["AI","Cursor","Agent","记忆系统"],"category":["🧩 AI框架与Agent","AI 应用核心范式"]},"headers":[],"relativePath":"vault/Knowledge/AI/Cursor 的记忆系统.md","filePath":"vault/Knowledge/AI/Cursor 的记忆系统.md","lastUpdated":1794320166000}'),c={name:"vault/Knowledge/AI/Cursor 的记忆系统.md"};function m(C,e,h,b,A,_){const t=a("VPNolebaseInlineLinkPreview"),s=a("NolebaseGitContributors"),n=a("NolebaseGitChangelog");return i(),u("div",null,[e[7]||(e[7]=p('<h1 id="cursor-删掉了自动记忆-这可能是三家-agent-里最诚实的选择" tabindex="-1">Cursor 删掉了自动记忆，这可能是三家 Agent 里最诚实的选择 <a class="header-anchor" href="#cursor-删掉了自动记忆-这可能是三家-agent-里最诚实的选择" aria-label="Permalink to “Cursor 删掉了自动记忆，这可能是三家 Agent 里最诚实的选择”">​</a></h1><p>另外两家在拼命让 Agent 记得更准，Cursor 做了件相反的事：<strong>把自动记忆功能删了。</strong></p><p>据官方论坛工作人员回复，chat Memories 自 2.1.x 起被有意移除。给出的理由很平淡：Memories 与 <code>.mdc</code> 规则差别不大，所以保留规则、删掉自动沉淀。</p><p>功能回退通常是负面信号。但仔细看它的替代方案，这次收缩其实有道理。</p><h2 id="一、删掉的到底是什么" tabindex="-1">一、删掉的到底是什么 <a class="header-anchor" href="#一、删掉的到底是什么" aria-label="Permalink to “一、删掉的到底是什么”">​</a></h2><p>chat Memories 原本的形态是：后台提取句子级事实，提议后经用户批准保存，项目级，仅本人可见。</p><p>这套设计和现在主流的&quot;自动记忆&quot;没有本质区别。它的价值在于&quot;你聊得越多，它越懂你的偏好&quot;。</p><p>它的风险也在这里：<strong>被提取的&quot;事实&quot;会过期。</strong> 半年前你说&quot;这个项目用 Python&quot;，今天已经换成 Go，但记忆还在。模型会带着过期前提给你提建议，而你不会察觉。</p><p>Cursor 的判断是：与其维护一个会过期的记忆，不如不要。</p><h2 id="二、记忆被拆成两件事" tabindex="-1">二、记忆被拆成两件事 <a class="header-anchor" href="#二、记忆被拆成两件事" aria-label="Permalink to “二、记忆被拆成两件事”">​</a></h2><p>删掉自动沉淀后，Cursor 把&quot;跨会话知道点什么&quot;拆成两条独立的路：</p><p><strong>稳定约定 → rules（人写，可评审，可进 git）</strong></p><p>规则分几类：</p><ul><li>项目规则 <code>.cursor/rules/*.mdc</code>，进 git</li><li>User Rules，随账号同步</li><li>Team Rules，后台下发，可以强制</li><li><code>AGENTS.md</code>（子树与父级合并，更具体的优先）</li></ul><p>冲突时优先级是 <strong>Team Rules &gt; Project Rules &gt; User Rules</strong>。</p><p>触发方式由 <code>alwaysApply</code>、<code>description</code>、<code>globs</code> 决定：总是注入、按描述判断、匹配文件挂载、仅 <code>@</code> 时生效。</p><p><strong>历史信息 → 检索（本地索引，按需命中）</strong></p><p>代码检索走 Instant Grep，在本机构建并查询索引。官方明确：不上传路径或代码建索引，<strong>也不存代码 embedding</strong>。</p><p>对话检索给历史 agent 转写建本地索引，并且已经作为 agent 可以主动调用的工具。</p><p>另有 Explore 子代理，在独立上下文里跑并行搜索，只回摘要。</p><h2 id="三、为什么这是诚实的" tabindex="-1">三、为什么这是诚实的 <a class="header-anchor" href="#三、为什么这是诚实的" aria-label="Permalink to “三、为什么这是诚实的”">​</a></h2><p>因为它承认了一件事：<strong>Agent 无法可靠判断&quot;哪句话值得长期记住&quot;。</strong></p><p>Claude Code 信任模型判断，但给了一堆排除规则来兜。Codex 信任后台模型，用时间剪枝和额度门控来兜。Cursor 的选择是不赌：要记住的东西由人来定（rules），其余靠现场检索。</p><p>这三种态度没有绝对高下，但有明确差异：</p><ul><li>Claude Code 的代价是索引会静默截断。</li><li>Codex 的代价是需要消耗额度，而且默认关闭。</li><li>Cursor 的代价是没有&quot;越用越懂你&quot;，每次都要靠规则和检索重建上下文。</li></ul><p>Cursor 换来的是：<strong>不会因为一条过期记忆，被悄悄带偏。</strong></p><h2 id="四、被忽略的细节" tabindex="-1">四、被忽略的细节 <a class="header-anchor" href="#四、被忽略的细节" aria-label="Permalink to “四、被忽略的细节”">​</a></h2><p>有几个设计容易被跳过，但能看出产品思路：</p><p><strong>兼容 <code>CLAUDE.md</code>。</strong> 按 <code>AGENTS.md</code> 读取，且总是应用，忽略 <code>alwaysApply</code>。它在主动兼容别家的规则文件，降低迁移成本。</p><p><strong>Projects 的共享上下文。</strong> 维护跨云/本地同步的上下文文件，各 agent 可以追加研究结论与操作知识。这算是一种&quot;团队级记忆&quot;，但仍然是文件形式，不是黑盒。</p><p><strong>Automations 的 Memories 是隔离的。</strong> 每个 automation 有独立的记忆，默认 <code>MEMORIES.md</code>，存在工作文件系统之外，不与其他 automation 混用。</p><p><strong>Agent SDK 的 memory hook。</strong> 每轮向 <code>memory/journal.jsonl</code> 追加一条 JSON，<strong>但模型没有 recall 工具</strong>。也就是说它只记录，不自动召回——把召回责任留给调用方。</p><p>最后这条尤其能说明态度：记录是自动的，召回是你的事。</p><h2 id="五、什么情况下该学-cursor" tabindex="-1">五、什么情况下该学 Cursor <a class="header-anchor" href="#五、什么情况下该学-cursor" aria-label="Permalink to “五、什么情况下该学 Cursor”">​</a></h2><p>如果你的场景满足这两条，Cursor 的路线更省心：</p><ol><li><strong>约定是稳定的。</strong> 团队规范、技术栈、代码风格，这些变化慢，写进规则一劳永逸。</li><li><strong>历史信息可以检索。</strong> 代码在本地、提交有记录，需要时搜一下比预先记着更准。</li></ol><p>反过来，如果约定经常变、或者上下文散落在聊天里无法检索，那么自动记忆仍有价值——但你必须给它配一套淘汰机制，否则迟早被污染。</p><h2 id="不确定性与边界" tabindex="-1">不确定性与边界 <a class="header-anchor" href="#不确定性与边界" aria-label="Permalink to “不确定性与边界”">​</a></h2><ul><li>&quot;移除 Memories&quot; 一条依据官方论坛工作人员回复与版本回退事实，官方文档已不再描述该功能。</li><li>2.0.x 版本仍保留该功能，判断时需核对版本。</li><li>第三方约定的 &quot;Memory Bank&quot; 是社区方案，不计入官方机制。</li><li>本文以 2026-11-09 访问的官方文档与论坛回复为准。</li></ul><hr>',40)),g("p",null,[e[3]||(e[3]=o("总览见 ",-1)),r(t,{href:"/nebula-blog/vault/Knowledge/AI/三大编码 Agent 都没有记忆库.html"},{default:l(()=>[...e[0]||(e[0]=[o("三大编码 Agent 都没有记忆库",-1)])]),_:1}),e[4]||(e[4]=o("，对照见 ",-1)),r(t,{href:"/nebula-blog/vault/Knowledge/AI/Codex 的记忆系统.html"},{default:l(()=>[...e[1]||(e[1]=[o("Codex 的记忆系统",-1)])]),_:1}),e[5]||(e[5]=o("、",-1)),r(t,{href:"/nebula-blog/vault/Knowledge/AI/Claude Code 的记忆系统.html"},{default:l(()=>[...e[2]||(e[2]=[o("Claude Code 的记忆系统",-1)])]),_:1}),e[6]||(e[6]=o("。",-1))]),r(s),r(n)])}const P=d(c,[["render",m]]);export{x as __pageData,P as default};
